--
-- Structure de la table `api_request_log`
--

CREATE TABLE `api_key` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `client_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `key_value` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `rate_limit` int NOT NULL DEFAULT '60',
  `is_active` tinyint(1) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `api_key_key_value_unique` (`key_value`)
) ENGINE = InnoDB AUTO_INCREMENT = 3 DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE `api_request_log` (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `api_key_id` bigint(20) UNSIGNED DEFAULT NULL,
  `method` varchar(8) NOT NULL,
  `endpoint` varchar(255) NOT NULL,
  `status_code` smallint(5) UNSIGNED NOT NULL,
  `duration_ms` int(10) UNSIGNED NOT NULL,
  `user_agent` varchar(512) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_key_time` (`api_key_id`,`created_at`),
  KEY `idx_created` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

--
-- Contraintes pour la table `api_request_log`
--
ALTER TABLE `api_request_log`
  ADD CONSTRAINT `api_request_log_api_key_id_foreign` FOREIGN KEY (`api_key_id`) REFERENCES `api_key` (`id`) ON DELETE SET NULL;

CREATE TABLE `logos` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `entity_type` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `entity_id` bigint unsigned NOT NULL,
  `from` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `until` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `logos_entity_type_entity_id_index` (`entity_type`, `entity_id`)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;